    # x: (768, 56, 56) CHW (batch of 1) or (1, 768, 56, 56)
    squeeze = (x.dim() == 3)
    if squeeze:
        x = x.unsqueeze(0)
    y = F.interpolate(x, size=(112, 112), mode='bilinear', align_corners=False)
    if squeeze:
        y = y.squeeze(0)
    return y.contiguous()

